let reduced=matchMedia('(prefers-reduced-motion: reduce)').matches, raf, canvas, c, width=0,height=0,stars=[],last=0;
export function setReduced(v){reduced=v;document.documentElement.dataset.motion=v?'reduced':'full';if(canvas){cancelAnimationFrame(raf);draw(0)}}
export function isReduced(){return reduced}
export function startStars(){canvas=document.querySelector('#cosmos');if(!canvas)return;c=canvas.getContext('2d');const size=()=>{width=innerWidth;height=innerHeight;let d=Math.min(devicePixelRatio||1,2);canvas.width=width*d;canvas.height=height*d;c.setTransform(d,0,0,d,0,0);stars=Array.from({length:Math.min(100,Math.round(width*height/17000))},()=>({x:Math.random()*width,y:Math.random()*height,r:Math.random()*1.1+.25,a:Math.random()*.6+.15,p:Math.random()*6.28}))};size();addEventListener('resize',size,{passive:true});document.addEventListener('visibilitychange',()=>{cancelAnimationFrame(raf);if(!document.hidden)draw(0)});draw(0)}
function draw(now){if(!c)return;if(now-last>40||!now||reduced){c.clearRect(0,0,width,height);for(const s of stars){const a=s.a*(reduced?1:.75+Math.sin(now*.0005+s.p)*.25);c.fillStyle=`rgba(215,224,255,${a})`;c.beginPath();c.arc(s.x,s.y,s.r,0,Math.PI*2);c.fill()}last=now}if(!reduced&&!document.hidden)raf=requestAnimationFrame(draw)}
export function burst(element,color='#e8c67f',count=18){if(reduced||!element)return;const r=element.getBoundingClientRect();for(let i=0;i<count;i++){let p=document.createElement('i');p.className='spark';p.style.background=color;p.style.left=(r.left+r.width/2)+'px';p.style.top=(r.top+r.height/2)+'px';document.body.append(p);let a=Math.PI*2*i/count,d=30+Math.random()*80;const anim=p.animate([{transform:'translate(0,0) scale(1)',opacity:1},{transform:`translate(${Math.cos(a)*d}px,${Math.sin(a)*d}px) scale(0)`,opacity:0}],{duration:500+Math.random()*400,easing:'cubic-bezier(.12,.6,.4,1)'});anim.onfinish=()=>p.remove()}}
export function photon(from,to,color){if(reduced||!from||!to)return;const a=from.getBoundingClientRect(),b=to.getBoundingClientRect();let p=document.createElement('i');p.className='flying-photon';p.style.setProperty('--c',color);document.body.append(p);let ax=a.left+a.width/2,ay=a.top+a.height/2,bx=b.left+b.width/2,by=b.top+b.height/2;let anim=p.animate([{left:ax+'px',top:ay+'px',transform:'scale(.4)',opacity:0},{left:ax+'px',top:ay+'px',transform:'scale(1.1)',opacity:1,offset:.15},{left:bx+'px',top:by+'px',transform:'scale(.6)',opacity:1}],{duration:780,easing:'cubic-bezier(.4,0,.2,1)'});anim.onfinish=()=>{p.remove();burst(to,color,22);to.classList.remove('ignite');void to.offsetWidth;to.classList.add('ignite')}}
export function celebrate(){if(reduced)return;for(let i=0;i<65;i++){let el=document.createElement('i');el.className='confetti';el.style.left=Math.random()*100+'vw';el.style.background=['#c8a7ff','#6cd7ff','#f1d28e','#f788b8'][i%4];document.body.append(el);let anim=el.animate([{transform:'translateY(-30px) rotate(0deg)',opacity:1},{transform:`translate(${Math.random()*180-90}px,105vh) rotate(${360+Math.random()*540}deg)`,opacity:0}],{duration:1800+Math.random()*1400,delay:Math.random()*650,easing:'cubic-bezier(.1,.5,.5,1)'});anim.onfinish=()=>el.remove()}}
export function ripple(button,x,y){if(reduced)return;let r=button.getBoundingClientRect(),s=document.createElement('span');s.className='ripple';s.style.left=(x-r.left)+'px';s.style.top=(y-r.top)+'px';button.append(s);s.addEventListener('animationend',()=>s.remove(),{once:true})}
